actions.script:
period = period == 'month' ? 'month' : 'all'
def zone = ec.user.timeZone.toZoneId()
def monthStart = ec.user.nowTimestamp.toInstant().atZone(zone).toLocalDate().withDayOfMonth(1)
def monthEnd = monthStart.plusMonths(1)
def start = java.sql.Timestamp.from(monthStart.atStartOfDay(zone).toInstant())
def end = java.sql.Timestamp.from(monthEnd.atStartOfDay(zone).toInstant())
def within = { date -> period == 'all' || (date && date >= start && date < end) }
sourceId = sourceCatalogue.any { it.leadSourceId == sourceId } ? sourceId : ''
campaignId = campaigns.any { it.campaignId == campaignId } ? campaignId : ''
def attributedLeads = allLeads.findAll { (!sourceId || (it.firstTouchSourceId ?: it.leadSourceId ?: 'Unknown') == sourceId) && (!campaignId || it.campaignId == campaignId) }
filteredLeads = attributedLeads.findAll { within(it.createdDate) }
def attributedLeadIds = attributedLeads*.leadId as Set
filteredOpps = allOpportunities.findAll { (!sourceId || (it.leadSourceId ?: 'Unknown') == sourceId) && (!campaignId || it.campaignId == campaignId) }
def selectedOppIds = filteredOpps*.salesOpportunityId as Set
def attributedActivities = allActivities.findAll {
    (!sourceId && !campaignId) || attributedLeadIds.contains(it.leadId) || selectedOppIds.contains(it.salesOpportunityId)
}
def completed = { row -> row.statusId == 'Completed' || (!row.statusId && !row.dueDate && row.activityDate) }
filteredActivities = attributedActivities.findAll { row ->
    within(completed(row) ? (row.completedDate ?: row.activityDate) : (row.dueDate ?: row.activityDate))
}
def currency = { row -> row.currencyUomId ?: 'Unspecified' }
def amountText = { deals, value ->
    deals.groupBy(currency).sort().collect { code, matching ->
        code + ' ' + ec.l10n.format(matching.sum(value), '#,##0.00##')
    }.join(' / ') ?: '—'
}
def amount = { row -> row.estimatedAmount ?: 0G }
def weighted = { row -> amount(row) * (row.estimatedProbability ?: 0G) }
def sourceNames = sourceCatalogue.collectEntries { [(it.leadSourceId):it.description] }
def allOpenDeals = filteredOpps.findAll { it.opportunityStageId !in ['SoClosedWon','SoClosedLost'] }
openOpps = allOpenDeals.findAll { period == 'all' || (it.estimatedCloseDate &&
    it.estimatedCloseDate.toLocalDate() >= monthStart && it.estimatedCloseDate.toLocalDate() < monthEnd) }
def wonDeals = filteredOpps.findAll { it.opportunityStageId == 'SoClosedWon' && within(it.wonDate) }
def lostDeals = filteredOpps.findAll { it.opportunityStageId == 'SoClosedLost' && within(it.lostDate) }
def periodDeals = openOpps + wonDeals + lostDeals
def leadsBySource = filteredLeads.groupBy { it.firstTouchSourceId ?: it.leadSourceId ?: 'Unknown' }
def dealsBySource = periodDeals.groupBy { it.leadSourceId ?: 'Unknown' }
def sourceKeys = (leadsBySource.keySet() + dealsBySource.keySet()).sort()
sourceRows = sourceKeys.collect { key ->
    def leads = leadsBySource[key] ?: []
    def opps = dealsBySource[key] ?: []
    def won = opps.findAll { it.opportunityStageId == 'SoClosedWon' }
    def qualified = leads.count { it.statusId in ['LeadQualified','LeadConverted'] }
    [sourceId:key, sourceName:sourceNames[key] ?: key, leads:leads.size(),
     qualified:qualified, qualifiedPercent:leads ? (qualified * 100 / leads.size()).intValue() : null,
     opportunities:opps.size(), won:won.size(), wonValue:amountText(won, amount)]
}
latestRows = filteredLeads.groupBy { it.latestTouchSourceId ?: it.leadSourceId ?: 'Unknown' }
    .collect { key, rows -> [sourceId:key, sourceName:sourceNames[key] ?: key, leads:rows.size()] }
    .sort { it.sourceName }
def settingsByStage = stageSettings.collectEntries { [(it.opportunityStageId): it] }
def stageName = { stage -> settingsByStage[stage.opportunityStageId]?.displayName ?: stage.description }
pipelineTotal = amountText(openOpps, amount)
weightedTotal = amountText(openOpps, weighted)
def stageNames = stages.collectEntries { [(it.opportunityStageId): stageName(it)] }
def stageOrder = stages.collectEntries { [(it.opportunityStageId):settingsByStage[it.opportunityStageId]?.sequenceNum ?: it.sequenceNum] }
forecastRows = openOpps.groupBy { it.opportunityStageId }.collectMany { id, matching ->
    matching.groupBy(currency).collect { code, deals ->
        [stageName:stageNames[id] ?: id ?: 'Unspecified', sequenceNum:stageOrder[id] ?: Integer.MAX_VALUE,
         currency:code, deals:deals.size(), amount:deals.sum(amount), weighted:deals.sum(weighted)]
    }
}.sort { a, b -> a.sequenceNum <=> b.sequenceNum ?: a.stageName <=> b.stageName ?: a.currency <=> b.currency }
categoryRows = periodDeals.groupBy(currency).sort().collect { code, deals ->
    def amounts = deals.groupBy { deal ->
        if (deal.opportunityStageId == 'SoClosedWon') return 'Closed'
        if (deal.opportunityStageId == 'SoClosedLost') return 'Omitted'
        return settingsByStage[deal.opportunityStageId]?.forecastCategory ?: 'Pipeline'
    }.collectEntries { category, matching -> [(category):matching.sum(amount)] }
    [currency:code, pipeline:amounts.Pipeline ?: 0G, bestCase:amounts['Best Case'] ?: 0G,
     commitValue:amounts.Commit ?: 0G, closed:amounts.Closed ?: 0G, omitted:amounts.Omitted ?: 0G]
}
def lastCompleted = [:]
allActivities.each { activity ->
    def id = activity.salesOpportunityId
    def timestamp = activity.completedDate ?: activity.activityDate
    if (id && completed(activity) && timestamp && (!lastCompleted[id] || timestamp > lastCompleted[id])) lastCompleted[id] = timestamp
}
def now = ec.user.nowTimestamp.time
staleRows = []
openOpps.each { deal ->
    def stage = deal.opportunityStageId
    def configuredDays = settingsByStage[stage]?.staleAfterDays
    int limitDays = configuredDays != null ? configuredDays : 14
    def updated = [deal.lastUpdatedStamp, lastCompleted[deal.salesOpportunityId]].findAll { it != null }.max()
    if (limitDays > 0 && updated && now - updated.time >= limitDays * 86400000L) {
        staleRows << [salesOpportunityId:deal.salesOpportunityId, opportunityName:deal.opportunityName,
            stageName:stageNames[stage] ?: stage, lastActivity:updated, limitDays:limitDays,
            idleDays:(now - updated.time).intdiv(86400000L)]
    }
}
staleRows.sort { a, b -> b.idleDays <=> a.idleDays ?: a.salesOpportunityId <=> b.salesOpportunityId }
completedActivities = filteredActivities.count(completed)
def scheduled = attributedActivities.findAll { it.statusId == 'Scheduled' }
overdueRows = scheduled.findAll { it.dueDate && it.dueDate < ec.user.nowTimestamp }.sort { it.dueDate }
overdueActivities = overdueRows.size()
def owner = { record -> record.assignedToUserId }
def openLeads = attributedLeads.findAll { it.statusId !in ['LeadLost','LeadConverted'] }
def leadCounts = openLeads.countBy(owner)
def dealCounts = allOpenDeals.countBy(owner)
def scheduledCounts = scheduled.countBy(owner)
def overdueCounts = overdueRows.countBy(owner)
def owners = (leadCounts.keySet() + dealCounts.keySet() + scheduledCounts.keySet()).sort { it ?: '' }
workloadRows = owners.collect { id ->
    [ownerName:id ?: 'Unassigned', openLeads:leadCounts[id] ?: 0, openDeals:dealCounts[id] ?: 0,
     scheduledCount:scheduledCounts[id] ?: 0, overdueCount:overdueCounts[id] ?: 0]
}
def statusCounts = filteredLeads.countBy { it.statusId }
leadStatusRows = leadStatuses.collect { [statusName:it.description, leads:statusCounts.remove(it.statusId) ?: 0] }
leadStatusRows.addAll(statusCounts.collect { id, count -> [statusName:id ?: 'Unspecified', leads:count] })
unassignedLeads = openLeads.count { !it.assignedToUserId }
def scheduledLeadIds = allActivities.findAll { it.statusId == 'Scheduled' && it.leadId }.collect { it.leadId } as Set
unattendedLeads = openLeads.count { !scheduledLeadIds.contains(it.leadId) }
wonCount = wonDeals.size()
lostCount = lostDeals.size()
winRate = wonCount + lostCount ? (wonCount * 100 / (wonCount + lostCount)).intValue() : null
lostRows = lostDeals.groupBy { it.lostReason ?: 'Unspecified' }.collect { key, rows ->
        [reason:key, deals:rows.size(), amount:amountText(rows, amount)]
    }
